INSERT INTO "user_imports" ("id","user_id","kind","text","pinyin","meaning","tags","payload","status","created_at","updated_at") VALUES (3,6,'problem','8. 王叔叔在桂林龙脊梯田步行观光，他从景区门口出发去观景台，6分钟走了360米，再走100米就到中点。从景区门口到观景台全程有多少米？（可以先画图，再解答）
