INSERT INTO "user_imports" ("id","user_id","kind","text","pinyin","meaning","tags","payload","status","created_at","updated_at") VALUES (5,6,'problem','某景区的儿童票每张8元，每张成人票的价钱是每张儿童票的3倍。每张成人票比每张儿童票贵多少元？','','','','{"topic":"数学应用题","sentences":[{"text":"某景区的儿童票每张8元，","is_key":true,"highlight":"儿童票：每张8元"},{"text":"每张成人票的价钱是每张儿童票的3倍。","is_key":true,"highlight":"成人票：是儿童票的3倍"},{"text":"每张成人票比每张儿童票贵多少元？","is_key":false,"highlight":""}],"total_key_points":2,"quantities":[{"name":"儿童票","value":8,"unit":"元"},{"name":"成人票","value":null,"unit":"元"}],"relations":[{"a":"成人票","b":"儿童票","type":"times","amount":3}]}','active','2026-08-09 02:15:33','2026-08-09 02:15:33');
