INSERT INTO "quest_sessions" ("id","user_id","question","plan_json","history_json","step_index","status","created_at","updated_at","sub_json","sub_level") VALUES (1,38,'科技书的本数是故事书的3倍，故事书有45本，科技书有多少本？','[{"type": "concept", "question": "你知道『几倍』是什么意思吗？", "options": ["知道", "不确定", "不知道"], "answer_index": 0, "explain": "想想：如果你有2块糖，我是你的3倍，我就有6块糖，这就是3倍。", "concept": "『几倍』表示一个数量是另一个数量的多少份，比如3倍就是3个那么多。生活例子：你吃1个苹果，爸爸吃3个，爸爸的就是你的3倍。"}, {"type": "understand", "question": "题目中谁的本数是故事书的3倍？", "options": ["科技书", "故事书", "一共的本数"], "answer_index": 0, "explain": "再读第一句『科技书的本数是故事书的3倍』，抓住主语是谁。", "concept": ""}, {"type": "extract", "question": "题目里告诉我们故事书有多少本？", "options": ["45本", "3本", "不知道"], "answer_index": 0, "explain": "找数字，题目第二句直接说了『故事书有45本』。", "concept": ""}, {"type": "relation", "question": "科技书和故事书的关系是什么？", "options": ["科技书=故事书×3", "科技书=故事书+3", "科技书=故事书-3"], "answer_index": 0, "explain": "『是故事书的3倍』就是科技书等于故事书的3份，想想乘法。", "concept": ""}, {"type": "formula", "question": "根据关系，科技书的算式应该怎么列？", "options": ["45×3", "45÷3", "45+3"], "answer_index": 0, "explain": "基准量是故事书的45本，3倍就是乘以3，别选除或加。", "concept": ""}, {"type": "summary", "question": "这类题的口诀是？", "options": ["A是B的几倍→A=B×倍数", "A是B的几倍→A=B÷倍数", "A是B的几倍→A=B+倍数"], "answer_index": 0, "explain": "记住：找到基准量B，用乘法算A，今后就能秒答。", "concept": ""}]','[{"step": 0, "answer": "知道", "correct": true}, {"step": 1, "answer": "科技书", "correct": true}, {"step": 2, "answer": "45本", "correct": true}, {"step": 3, "answer": "科技书=故事书×3", "correct": true}, {"step": 4, "answer": "45×3", "correct": true}, {"step": 5, "answer": "A是B的几倍→A=B×倍数", "correct": true}]',6,'done','2026-08-11 23:00:36','2026-08-11 23:00:37','',0);
INSERT INTO "quest_sessions" ("id","user_id","question","plan_json","history_json","step_index","status","created_at","updated_at","sub_json","sub_level") VALUES (2,6,'4. 小明准备了一篇840字的稿件参加“保护环境”演讲比赛。比赛规定每名同学的演讲时间不能超过5分钟,他能在规定时间内完成演讲稿吗? 我平均每分钟说202个字。','[{"type": "concept", "question": "你知道『平均每分钟说202个字』中的『平均』是什么意思吗？", "options": ["知道", "不确定", "不知道"], "answer_index": 0, "explain": "想想如果有时快有时慢，平均就是取一个差不多的速度。", "concept": "平均就是把不均匀的速度拉平，比如你有时每分钟说100字，有时说300字，平均下来可能每分钟说202字，就像把总字数均匀分到每一分钟。"}, {"type": "understand", "question": "这道题要我们判断什么？", "options": ["小明能不能在5分钟内说完840字", "小明准备了几个字", "演讲比赛有多少人参加"], "answer_index": 0, "explain": "题目问『他能在规定时间内完成演讲稿吗』，规定时间是什么？再读读题。", "concept": ""}, {"type": "extract", "question": "小明每分钟能说多少字？", "options": ["202个字", "840个字", "5分钟"], "answer_index": 0, "explain": "找到那句『我平均每分钟说202个字』，这就是他的速度。", "concept": ""}, {"type": "extract", "question": "演讲比赛规定的时间限制是多少？", "options": ["5分钟", "840秒", "202分钟"], "answer_index": 0, "explain": "题目里说『演讲时间不能超过5分钟』，这个数很关键。", "concept": ""}, {"type": "relation", "question": "要判断5分钟能不能说完840字，需要先算出什么？", "options": ["5分钟能说多少字", "840字需要多少分钟", "小明写了多少字"], "answer_index": 0, "explain": "比较时间或字数，先算出5分钟的总量，再和840比。", "concept": ""}, {"type": "formula", "question": "如果每分钟说202字，说5分钟，总共能说多少字？算式是？", "options": ["202×5", "840÷202", "202+5"], "answer_index": 0, "explain": "每分钟的字数乘以分钟数就是总字数，别选成除法哦。", "concept": ""}, {"type": "summary", "question": "做完这题，你发现这类『时间够不够』的问题，口诀是什么？", "options": ["速度×时间=总量，再和总量比", "时间÷速度=总量", "速度+时间=总量"], "answer_index": 0, "explain": "记住先算规定时间内能完成的量，再和需要完成的量比较。", "concept": ""}]','[{"step": 0, "answer": "不知道", "correct": false}, {"step": 1, "answer": "小明能不能在5分钟内说完840字", "correct": true}, {"step": 2, "answer": "202个字", "correct": true}, {"step": 3, "answer": "5分钟", "correct": true}, {"step": 4, "answer": "5分钟能说多少字", "correct": true}, {"step": 5, "answer": "202×5", "correct": true}, {"step": 6, "answer": "速度×时间=总量，再和总量比", "correct": true}]',7,'done','2026-08-12 04:27:39','2026-08-12 04:33:16','',0);
INSERT INTO "quest_sessions" ("id","user_id","question","plan_json","history_json","step_index","status","created_at","updated_at","sub_json","sub_level") VALUES (3,39,'科技书的本数是故事书的3倍，故事书有45本，科技书有多少本？','[{"type": "concept", "question": "你知道『几倍』是什么意思吗？", "options": ["知道", "不确定", "不知道"], "answer_index": 0, "explain": "想想你有的糖果数量，倍数就是另一个数量的几份。", "concept": "『几倍』就是另一个数量有几个这么多。比如你有2颗糖，我有你的3倍，就是我有3个2颗，共6颗。"}, {"type": "understand", "question": "这道题讲的是谁和谁的书？", "options": ["科技书和故事书", "科技书和漫画书", "故事书和漫画书"], "answer_index": 0, "explain": "题目开头就说科技书的本数是故事书的3倍，再找找谁有具体数量。", "concept": ""}, {"type": "understand", "question": "最后要问什么？", "options": ["科技书有多少本", "故事书有多少本", "两种书一共多少本"], "answer_index": 0, "explain": "题目最后一句是『科技书有多少本？』，我们要求的就是科技书的本数。", "concept": ""}, {"type": "extract", "question": "故事书有多少本？", "options": ["45本", "3本", "15本"], "answer_index": 0, "explain": "题目里直接说『故事书有45本』，找这个明确的数字。", "concept": ""}, {"type": "extract", "question": "科技书和故事书是什么关系？", "options": ["科技书是故事书的3倍", "故事书是科技书的3倍", "一样多"], "answer_index": 0, "explain": "题目第一句就是『科技书的本数是故事书的3倍』，基准量是故事书。", "concept": ""}, {"type": "relation", "question": "谁是基准量？也就是把谁看成1份？", "options": ["故事书", "科技书", "两种书合计"], "answer_index": 0, "explain": "『是故事书的3倍』，故事书是那个1份，科技书是3份。", "concept": ""}, {"type": "relation", "question": "科技书可以看成几个故事书那么多？", "options": ["3个", "1个", "45个"], "answer_index": 0, "explain": "3倍就是3个故事书的量，故事书有45本，就是3个45。", "concept": ""}, {"type": "relation", "question": "要求科技书，应该用乘法还是除法？", "options": ["乘法", "除法", "加法"], "answer_index": 0, "explain": "求一个数的几倍是多少，用乘法，因为要算3个45。", "concept": ""}, {"type": "formula", "question": "先算什么？就是求3个45是多少，算式怎么列？", "options": ["45×3", "45÷3", "45+3"], "answer_index": 0, "explain": "3倍就是3个45相加，用乘法更简单，把45和3相乘。", "concept": ""}, {"type": "formula", "question": "45×3的算式里，45表示什么？", "options": ["故事书的数量", "科技书的数量", "倍数"], "answer_index": 0, "explain": "45是故事书的本数，也是基准量，要和倍数3相乘。", "concept": ""}, {"type": "formula", "question": "列式计算时，先算45×3的积，结果就是科技书的本数。请选择正确的算式写法。", "options": ["45×3=135", "45÷3=15", "45×3=120"], "answer_index": 0, "explain": "45×3，3个45相加是135，不是120或15。", "concept": ""}, {"type": "summary", "question": "总结一下：求一个数的几倍是多少，应该怎么做？", "options": ["用乘法：这个数×倍数", "用除法：这个数÷倍数", "用加法：这个数+倍数"], "answer_index": 0, "explain": "记住口诀：求几倍，用乘法，基准量乘倍数。", "concept": ""}]','[{"step": 0, "answer": "不知道", "correct": false}, {"step": 0, "answer": "知道", "correct": true, "kind": "sub"}, {"step": 0, "answer": "知道", "correct": true}]',1,'active','2026-08-12 05:06:14','2026-08-12 05:06:16','',0);
