INSERT INTO "chinese_unit_knowledge" ("id","unit","lesson","category","page","content","knowledge_points","question_types","created_at","image_path") VALUES (27,'未分类','','写作指导','','【题1】补充下面的对话。
小红:我的名字是奶奶起的,“红”字是奶奶对我们一家人的期待,她希望我们一家人的生活红红火火,幸福美满。你的名字有什么含义呢?
