INSERT INTO "chinese_unit_knowledge" ("id","unit","lesson","category","page","content","knowledge_points","question_types","created_at","image_path") VALUES (44,'第三单元','','单元知识清单','','【题1】辨字组词
占（占领） 召（召唤） 救（救命） 咬（咬牙） 刚（刚才）
战（战斗） 绍（介绍） 球（地球） 饺（饺子） 钢（钢铁）

【题2】词语盘点
