INSERT INTO "chinese_question_items" ("id","category","question","answer","unit","lesson","page","source","created_at") VALUES (193,'积累背诵','(3)与“萧萧梧叶送寒声，江上秋风动客情”表达的感情相似的诗句是（ ）
