INSERT INTO "chinese_question_items" ("id","category","question","answer","unit","lesson","page","source","created_at") VALUES (234,'字音','读准字音。平舌音：舱（cāng）；翘舌音：耍（shuǎ）；前鼻音：衔（xián）欠（qiàn）；后鼻音：舱（cāng）鹦（yīng）英（yīng）茸（róng）拢（lǒng）','','第五单元','《搭船的鸟》','','scanned','2026-08-12 12:06:49');
