INSERT INTO "chinese_question_items" ("id","category","question","answer","unit","lesson","page","source","created_at") VALUES (237,'字词书写','字形辨识。要（要求）蒲（蒲公英）静（安静）搭（搭档）摇（摇动）；耍（玩耍）捕（捕鱼）争（斗争）塔（宝塔）遥（遥远）；吞（吞下）悄（静悄悄）欠（亏欠）拢（合拢）披（披风）；吴（吴国）俏（俊俏）吹（吹风）笼（笼子）被（被子）','','第五单元','《搭船的鸟》','','scanned','2026-08-12 12:06:49');
