INSERT INTO "chinese_textbook_pages" ("id","page","unit","lesson","page_type","content","knowledge_points","created_at","image_path") VALUES (7,'7','未分类','','语文园地','【题1】在班里组织几个兴趣小组吧！试着给每个兴趣小组取个响亮的名字，吸引有相同爱好的同学一起开展活动。
