INSERT INTO "chinese_textbook_pages" ("id","page","unit","lesson","page_type","content","knowledge_points","created_at","image_path") VALUES (40,'40','未分类','','课后练习','【题1】预测的方法对你的阅读有哪些帮助？你是怎么运用预测来阅读的？和同学交流你的心得。

【题2】读一读，写一写。
恒心  神圣  萌发  妥当
