INSERT INTO "chinese_textbook_pages" ("id","page","unit","lesson","page_type","content","knowledge_points","created_at","image_path") VALUES (48,'48','第三单元','在牛肚子里旅行','课后练习','【题1】
dā yìng jí juǎn gū lù chǐ jiáo tūn wèi yàn
答 应 及 卷 骨 碌 齿 嚼 吞 胃 咽
旅 另 睛 及 卷 救 命
尾 齿 胃 管 刚 咬

【题2】
