INSERT INTO "chinese_fts" ("content","src_type","src_id") VALUES ('本单元以“金秋时节”为主题，编排了古诗三首（《望洞庭》《山行》《夜书所见》），和《铺满金色巴掌的水泥道》《秋天的雨》《听听，秋的声音》三篇选文，从不同角度展示秋天别样的风景。我们在学习时要注意“运用多种方法理解难懂的词语。”本单元旨在让我们学会运用多种方法（借助图画、查字典、联系上下文、联系生活经验等）理解难懂的词语。','question',28);
