INSERT INTO "chinese_fts" ("content","src_type","src_id") VALUES ('读准字音：平舌音：粗（cū） 猜（cāi） 促（cù）；翘舌音：诗（shī） 枝（zhī） 石（shí）；后鼻音：声（shēng） 明（míng） 听（tīng） 影（yǐng） 静（jìng） 停（tíng） 经（jīng）。多音字：觉 jiào（睡觉） jué（感觉）。其他读音：径（jìng） 斜（xié） 霜（shuāng） 赠（zèng） 刘（liú） 盖（gài） 菊（jú） 残（cán） 犹（yóu） 傲（ào） 君（jūn） 橙（chéng） 橘（jú） 挑（tiǎo） 促（cù） 深（shēn）。','question',373);
