INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (2,'第二单元','舟夜书所见','清·查慎行','poem','月黑见渔灯，孤光一点萤。微微风簇浪，散作满河星。','','26','','2026-08-14 09:55:21');
INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (3,'第六单元','早发白帝城','唐·李白','poem','朝辞白帝彩云间，千里江陵一日还。两岸猿声啼不住，轻舟已过万重山。','','82','','2026-08-14 09:55:21');
INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (4,'第七单元','采莲曲','唐·王昌龄','poem','荷叶罗裙一色裁，芙蓉向脸两边开。乱入池中看不见，闻歌始觉有人来。','','94','','2026-08-14 09:55:21');
INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (5,'第三单元','日积月累·待人处己','','saying','不迁怒，不贰过。——《论语》；爱人若爱其身。——《墨子》；仁者爱人，有礼者敬人。——《孟子》；与人善言，暖于布帛；伤人以言，深于矛戟。——《荀子》','《论语》《墨子》《孟子》《荀子》','39','','2026-08-14 09:55:21');
INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (6,'第四单元','日积月累·团结合作','','saying','人心齐，泰山移。二人同心，其利断金。三个臭皮匠，顶个诸葛亮。','谚语','56','','2026-08-14 09:55:21');
INSERT INTO "chinese_recitation_items" ("id","unit","title","author","kind","content","source_ref","page","image_path","created_at") VALUES (7,'第八单元','日积月累·意志学问','','saying','士不可以不弘毅，任重而道远。——《论语》；志不强者智不达，言不信者行不果。——《墨子》；锲而舍之，朽木不折；锲而不舍，金石可镂。——《荀子》','《论语》《墨子》《荀子》','108','','2026-08-14 09:55:21');
