INSERT INTO "student_profiles" ("id","user_id","module","session_count","last_content","mistakes","mastered","updated_at","created_at") VALUES (1,45,'chinese',6,'春天来了，这句话你会怎么教孩子朗读','["形近字（如“跑”和“抱”）易混淆", "掌握：偏旁部首识字兴趣浓厚", "跑/抱", "掌握：偏旁部首识字", "“一”的变调规则不熟悉", "形近字（切/分）易混淆", "掌握：能运用偏旁部首识字法记忆汉字", "辨析形近字。", "形近字辨析", "掌握：偏旁部首识字法"]','["偏旁部首识字兴趣浓厚", "偏旁部首识字", "能运用偏旁部首识字法记忆汉字", "辨析形近字。", "偏旁部首识字法"]','2026-08-18 12:51:56','2026-08-18 11:07:46');
